<script setup>import {ref,onMounted,onBeforeUnmount} from 'vue';import LinIcon from './LinIcon.vue';const visible=ref(false);function scroll(){visible.value=scrollY>350;}onMounted(()=>addEventListener('scroll',scroll,{passive:true}));onBeforeUnmount(()=>removeEventListener('scroll',scroll));function top(){window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}</script><template><button v-if="visible" class="lin-compass" aria-label="回到顶部" @click="top"><LinIcon name="arrow" :size="19"/><small>TOP</small></button></template><style scoped>.lin-compass{position:fixed;bottom:25px;right:22px;width:43px;height:59px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;border:1px solid var(--lin-line);border-radius:24px;background:var(--card-bg);color:var(--lin-accent);z-index:1900;box-shadow:0 4px 15px #2221}.lin-compass svg{transform:rotate(-90deg)}small{font-size:7px;letter-spacing:1px}@media(max-width:600px){.lin-compass{right:10px;bottom:15px;width:34px;height:50px}}</style>
